for f in $(cat "$TMPDIR/timer_spinlock_files.txt"); do
  python3 - "$f" << 'PYEOF'
import re, sys
path = sys.argv[1]
src = open(path, errors='ignore').read()
lines = src.split('\n')
# find timer callback function names via timer_setup(&x->t, cb, ...) or setup_timer(&t, cb, ...)
cbs = set()
for m in re.finditer(r'timer_setup\s*\(\s*&[\w\.\>\-\>\[\]]+,\s*(\w+)\s*,', src):
    cbs.add(m.group(1))
for m in re.finditer(r'setup_timer\s*\(\s*&[\w\.\>\-\>\[\]]+,\s*(\w+)\s*,', src):
    cbs.add(m.group(1))
for m in re.finditer(r'setup_deferrable_timer\s*\(\s*&[\w\.\>\-\>\[\]]+,\s*(\w+)\s*,', src):
    cbs.add(m.group(1))
if not cbs:
    sys.exit()
# find lock names in those callback bodies
def body(name):
    m = re.search(r'(?:^|\n)[ \t]*(?:static\s+)?(?:void|enum\s+\w+|int|irqreturn_t|unsigned\s+long|long|u\d+|bool)[ \t\*]+'+re.escape(name)+r'\s*\(', src)
    if not m: return None
    i = m.end()
    depth = 0; started = False
    out = []
    while i < len(src):
        c = src[i]
        if c == '{': depth += 1; started = True
        elif c == '}':
            depth -= 1
            if started and depth == 0:
                return ''.join(out)
        if started: out.append(c)
        i += 1
    return None
for cb in cbs:
    b = body(cb)
    if not b: continue
    for lm in re.finditer(r'spin_lock(?:_irqsave|_irq|_bh)?\s*\(\s*&([\w\.\>\-\>\[\]]+)', b):
        print(f"{path}\tCB={cb}\tLOCK={lm.group(1)}\tMODE={lm.group(0).split('(')[0].strip()}")
PYEOF
done > "$TMPDIR/cb_locks.txt" 2>/dev/null; sort -u "$TMPDIR/cb_locks.txt" | wc -l; sort -u "$TMPDIR/cb_locks.txt" | head -40

grep -rln "spin_lock(" --include="*.c" drivers 2>/dev/null | wc -l && mkdir -p /tmp/i017 && cat > /tmp/i017/gen_list.py << 'EOF'
import os, re, sys

root = "."
results = {}  # path -> dict of counts
patterns = {
    "timer_setup": re.compile(r"timer_setup\s*\("),
    "setup_timer": re.compile(r"setup_timer\s*\("),
    "DEFINE_TIMER": re.compile(r"DEFINE_TIMER\s*\("),
    "hrtimer_init": re.compile(r"hrtimer_init\s*\("),
    "delayed_work": re.compile(r"INIT_DELAYED_WORK|DECLARE_DELAYED_WORK"),
    "spin_lock_plain": re.compile(r"(?<![a-zA-Z0-9_])spin_lock\s*\("),
    "spin_lock_bh": re.compile(r"spin_lock_(bh|irqsave|irq|irqrestore|nested|bh_unlock)\s*\(|local_bh_disable|spin_lock_bh"),
}
for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if not (fn.endswith(".c") or fn.endswith(".h")):
            continue
        p = os.path.join(dirpath, fn)
        try:
            with open(p, "r", errors="ignore") as f:
                text = f.read()
        except OSError:
            continue
        counts = {}
        for k, pat in patterns.items():
            counts[k] = len(pat.findall(text))
        if counts["timer_setup"] or counts["setup_timer"] or counts["DEFINE_TIMER"] or counts["hrtimer_init"] or counts["delayed_work"]:
            results[p] = counts
for p, c in sorted(results.items()):
    print(f"{p}\tT={c['timer_setup']}\tST={c['setup_timer']}\tDT={c['DEFINE_TIMER']}\tHRT={c['hrtimer_init']}\tDW={c['delayed_work']}\tPL={c['spin_lock_plain']}\tBH={c['spin_lock_bh']}")
EOF
python3 /tmp/i017/gen_list.py > /tmp/i017/timer_files.txt && wc -l /tmp/i017/timer_files.txt

T="$TMPDIR/i017"; cat > "$T/gen_list.py" << 'EOF'
